parameters.messages:
=[{
  'role': 'system',
  'content': $input.first().json.systemPrompt
}, {
  'role': 'user',
  'content': `User input: ${$input.first().json.userInput}\n\nPlease create a content plan for a LinkedIn post.`
}]

parameters.functionCode:
const response = $input.first().json.choices[0].message.content;

try {
  const plan = JSON.parse(response);
  return {
    ...plan,
    chatId: $input.first().json.chatId,
    rawResponse: response
  };
} catch (e) {
  // Fallback if JSON parsing fails
  return {
    topic: 'Content Creation',
    themes: ['Professional development'],
    audience: 'LinkedIn professionals',
    structure: ['Introduction', 'Main content', 'Conclusion'],
    keyPoints: response.split('\n').filter(p => p.trim()),
    tone: 'Professional',
    considerations: ['Engagement', 'Value addition'],
    chatId: $input.first().json.chatId,
    rawResponse: response
  };
}
